public class StarTriangle {

    public static String starTriangle(int n) {
        StringBuilder sb = new StringBuilder();
        for (int row = 1; row <= n; row++) {
            for (int col = 0; col < row; col++) {
                sb.append('*');
            }
            if (row < n) {
                sb.append('\n');
            }
        }
        return sb.toString();
    }
}
